async function main() {
  const isDryRun = process.env.DRY_RUN !== 'false';
  
  if (!process.env.MONGODB_URI) {
    console.error("❌ MONGODB_URI is not set!");
    process.exit(1);
  }

  console.log("=".repeat(55));
  console.log(" FIX GIN CATEGORY — Migration Script");
  console.log("=".repeat(55));
  console.log(` Mode:     ${isDryRun ? '🔍 DRY RUN (no changes)' : '⚠️ LIVE RUN (will update DB)'}`);
  console.log(` MongoDB:  ${process.env.MONGODB_URI.split('@').pop()}`);
  console.log("=".repeat(55));
  console.log("");

  await mongoose.connect(process.env.MONGODB_URI);
  
  // Find the 'gin' category and other categories
  const ginCategory = await Category.findOne({ slug: 'gin' });
  if (!ginCategory) {
    console.error("❌ Could not find GIN category in DB!");
    process.exit(1);
  }

  // Fetch target categories to get their ObjectIds
  const targetCategoryNames = [...new Set(productCategoryMappings.map(m => m.targetCategory))];
  const targetCategoryMap = {};
  
  for (const tName of targetCategoryNames) {
    // Attempt basic mapping logic to slugs
    let slug = tName.toLowerCase().replace(/_/g, '-').replace(/ & /g, '-').replace(/ /g, '-');
    if (tName === 'LIQUEUR_SPIRITS') slug = 'liqueur';
    if (tName === 'JUICE_DRINKS') slug = 'juice';
    if (tName === 'GUM_MINTS') slug = 'gum-mints';
    if (tName === 'ENERGY_DRINKS') slug = 'energy-drinks';
    
    const cat = await Category.findOne({ slug: slug });
    if (!cat) {
      // Fallback searches
      const allMatches = await Category.find({ name: new RegExp(tName.replace(/_/g, ' '), 'i') });
      if (allMatches.length > 0) {
          targetCategoryMap[tName] = allMatches[0]._id;
      } else {
          console.warn(`⚠️ Could not find target category for mappings: ${tName}`);
      }
    } else {
      targetCategoryMap[tName] = cat._id;
    }
  }

  const results = {
    moved: 0,
    notFound: 0,
    errors: 0,
    byCategory: {}
  };

  const beforeCount = await Product.countDocuments({ category: ginCategory._id });

  for (const mapping of productCategoryMappings) {
    const { productId, targetCategory, name } = mapping;
    const targetCategoryId = targetCategoryMap[targetCategory];
    
    if (!targetCategoryId) {
      console.warn(`Skipping ${name} - no category ID for ${targetCategory}`);
      results.errors++;
      continue;
    }

    if (!isDryRun) {
      try {
        const res = await Product.updateOne(
          { _id: productId, category: ginCategory._id },
          { $set: { category: targetCategoryId } }
        );
        if (res.modifiedCount > 0) {
          results.moved++;
          results.byCategory[targetCategory] = (results.byCategory[targetCategory] || 0) + 1;
        } else {
          results.notFound++;
        }
      } catch (err) {
        console.error(`❌ Error updating ${productId}: ${err.message}`);
        results.errors++;
      }
    } else {
      results.moved++;
      results.byCategory[targetCategory] = (results.byCategory[targetCategory] || 0) + 1;
    }
  }

  const afterCount = isDryRun ? (beforeCount - results.moved) : await Product.countDocuments({ category: ginCategory._id });

  console.log("=".repeat(55));
  console.log(" MIGRATION SUMMARY");
  console.log("=".repeat(55));
  console.log(` Mode:           ${isDryRun ? '🔍 DRY RUN' : '⚠️ LIVE RUN'}`);
  console.log(` Before:         ${beforeCount} products in GIN`);
  console.log(` Moved/To Move:  ${results.moved} products`);
  console.log(` After:          ${afterCount} products in GIN`);
  console.log(` Not Found:      ${results.notFound}`);
  console.log(` Errors:         ${results.errors}`);
  console.log("");
  console.log(" Breakdown by target category:");
  Object.entries(results.byCategory)
    .sort((a, b) => b[1] - a[1])
    .forEach(([cat, count]) => {
      console.log(`   → ${cat.padEnd(20)} ${count} products`);
    });
  console.log("=".repeat(55));
  console.log("");

  if (isDryRun) {
    console.log(" 💡 To apply changes, run with: DRY_RUN=false");
  } else {
    console.log(" ✅ Changes applied successfully.");
  }
  
  await mongoose.disconnect();
  console.log(" ✅ Done. Disconnected from MongoDB.");
}

main().catch(console.error);
